const express = require('express');
const { DatabaseSync } = require('node:sqlite');
const { authenticateUser } = require('../auth');

const app = express();
app.use(express.json());
const db = new DatabaseSync('./storage/notifications.db');

app.patch('/api/notifications/:notificationId/status', authenticateUser, (req, res) => {
  const { notificationId } = req.params;
  const { status } = req.body;

  if (!['READ', 'DISMISSED'].includes(status)) {
    return res.status(400).json({ error: 'Invalid status' });
  }

  // Constrain update strictly to notifications owned by the authenticated user
  const stmt = db.prepare('UPDATE user_notifications SET status = ?, updated_at = ? WHERE id = ? AND user_id = ?');
  const result = stmt.run(status, Date.now(), notificationId, req.user.id);

  if (result.changes === 0) {
    return res.status(404).json({ error: 'Notification not found or access denied' });
  }

  res.json({ success: true, notificationId, status });
});

module.exports = app;
